import std::io;

fn main() s32 @public {
    io::print("value=%d\n", 42);
    return 0;
}

import std::io;

fn main() s32 @public {
    var file := io::openFile("data.txt", "r");

    if file == nullptr {
        io::printError("openFile");
        return 1;
    }

    var c: s32 = io::readCharFrom(file);

    if c != io::EOF {
        io::print("first byte=%d\n", c);
    }

    if io::closeFile(file) != 0 {
        return 1;
    }

    return 0;
}

