enum ExitCode @public {
    Ok: s32 = 0;
    InvalidInput: s32 = 1;
    IOError: s32 = 2;
}

fn codeOf(value: s32) s32 @public {
    if value == ExitCode=>Ok {
        return 0;
    }

    if value == ExitCode=>InvalidInput {
        return 1;
    }

    return ExitCode=>IOError;
}

